    INSERT INTO mcqs (topic_id, question, options, correct_index, explanation) VALUES
    (v_topic_id, 'A 92-year-old male named David is receiving home hospice care for terminal pancreatic cancer. He develops severe, refractory bone pain and hyperactive delirium with agitation that cannot be safely or effectively managed at home despite multiple increases in transdermal and sublingual opioid doses. What is the most appropriate next step under the Medicare hospice benefit?', '["Instruct the family to increase the opioid dose tenfold at home and use physical restraints to manage the delirium", "Prescribe oral acetaminophen and advise the family that delirium is a normal part of dying that cannot be treated", "Disenroll the patient from hospice immediately and admit them to the hospital ICU for emergency intubation and chemotherapy", "Refuse any change in care level, as home hospice patients are legally prohibited from leaving their residence", "Transfer the patient to a General Inpatient (GIP) hospice bed for short-term, intensive management of acute, refractory symptoms that cannot be controlled in the home setting"]'::jsonb, 4, 'Under the Medicare Hospice Benefit, **General Inpatient (GIP) care** is indicated for **short-term management of acute, refractory symptoms** (e.g., severe pain, uncontrollable delirium, intractable nausea, severe dyspnea) that **cannot be managed in other settings** (such as the home). GIP can be provided in an inpatient hospice unit, a skilled nursing facility, or a hospital. The focus remains entirely palliative, utilizing intensive nursing and medical adjustments to stabilize symptoms. Once the symptoms are controlled, the patient is transitioned back to home hospice care. (Ref: AGS Geriatrics At Your Fingertips; Hazzard''s Ch. 82; UWorld Step 2 CK)'),
